if (fork() == 0) {            /* child becomes the next filter */
    dup2(fds[0], STDIN_FILENO);
    close(fds[1]); close(fds[0]);
    execlp("gzip", "gzip", "-c", (char *)NULL);
}
close(fds[0]);                /* parent = source stage */
write(fds[1], buf, n);
close(fds[1]);                /* EOF downstream */
wait(NULL);

