typedef int (*stage_fn)(FILE *in, FILE *out);
struct stage { stage_fn run; const char *name; };
static const struct stage chain[] = {
    {drop_comments, "drop-comments"},
    {normalise,     "normalise"},
};
FILE *buf = fopen(input_path, "r");
for (size_t i = 0; i < sizeof chain / sizeof *chain; i++) {
    FILE *next = tmpfile();
    if (chain[i].run(buf, next) != 0) die(chain[i].name);
    rewind(next); fclose(buf); buf = next;
}
